; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCMIN (NTCMIN.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_goto_iftrue_n:	jp 13
kw_goto_ifzero_n:	jp 15
kw_forupv_n:	jp 25
kw_next1l_n:	jp 31
kw_next1v_n:	jp 33
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_add:		jp 53
kw_addl:		jp 54
kw_sublv:	jp 56
kw_4x:		jp 58
kw_mulvl:	jp 61
kw_divvl:	jp 64
kw_andvv:	jp 72
kw_scpltvl:	jp 80
kw_scplevl:	jp 82
kw_scpgtvl:	jp 84
kw_cpeqvl:	jp 96
kw_cpnevl:	jp 98
kw_strcpy:	jp 122
kw_strcat:	jp 124
kw_printzoscii:	jp 129
kw_printstrvar:	jp 130
kw_printint:	jp 132
kw_printnl:	jp 139
kw_inkey:	jp 145
